/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if(api.item.value.exclude){
    return 'info-circle-outline';
  }else {
    return 'inventory-circle-plus-outline';
  }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const infoItems = api.item.value.table_excluded_info;
    return {
        "label": infoItems.join('. ')
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    return {
        "label": api.item.value.table_label,
        "size": "sm",
        "variant": "tertiary"
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    return (api.state.coverageWeightsType === "automatic" || api.item.value.exclude == true);
}
